// TR_Validate_Input — v2.0 (Remediated)
// Purpose: Validate and adapt the inbound ThreadResolutionRequest.
// Supports BOTH nested (user contract) and flat (internal) input shapes.
// Nested shape: { request: { message: {...}, reply_context: {...}, resolution_policy: {...} }, idempotency_key }
// Flat shape: { message_id, tenant_id, channel, ... }
// Output: Validated flat request with _valid='true' or error with _valid='false'.

const items = $input.all();
const raw = items[0].json;

// --- ADAPTER LAYER: detect and normalize input shape ---
let req = {};

if (raw.request && raw.request.message) {
  // Nested (user contract) shape
  const msg = raw.request.message;
  const rc = raw.request.reply_context || raw.reply_context || {};
  const rp = raw.request.resolution_policy || raw.resolution_policy || {};
  req = {
    message_id: msg.id,
    tenant_id: raw.request.tenant_id,
    channel: msg.channel,
    direction: msg.direction,
    author_type: msg.author_type,
    normalized_content: msg.normalized_content,
    timestamp: msg.timestamp,
    source_message_ref: msg.source_message_ref,
    author_entity_id: msg.author_entity_id || null,
    thread_id: msg.thread_id || null,
    reply_to_message_id: rc.reply_to_message_id || null,
    reply_to_thread_id: rc.reply_to_thread_id || null,
    related_entity_ids: msg.related_entity_ids || [],
    metadata: msg.metadata || {},
    // Resolution policy (per-request thresholds)
    attach_threshold: rp.attach_threshold || null,
    reopen_threshold: rp.reopen_threshold || null,
    max_candidate_threads: rp.max_candidate_threads || null,
    allow_latent_reopen: rp.allow_latent_reopen !== undefined ? rp.allow_latent_reopen : true,
    allow_entity_assisted_match: rp.allow_entity_assisted_match !== undefined ? rp.allow_entity_assisted_match : true,
    ambiguity_margin: rp.ambiguity_margin || null,
    idempotency_key: raw.request.idempotency_key || raw.idempotency_key || null,
    // Preserve content variants for Phase 2
    llm_safe_content: msg.llm_safe_content || null,
    rag_safe_content: msg.rag_safe_content || null
  };
} else {
  // Flat (internal) shape — backward compatible
  req = { ...raw };
  req.reply_to_thread_id = raw.reply_to_thread_id || null;
  req.attach_threshold = raw.attach_threshold || null;
  req.reopen_threshold = raw.reopen_threshold || null;
  req.max_candidate_threads = raw.max_candidate_threads || null;
  req.allow_latent_reopen = raw.allow_latent_reopen !== undefined ? raw.allow_latent_reopen : true;
  req.allow_entity_assisted_match = raw.allow_entity_assisted_match !== undefined ? raw.allow_entity_assisted_match : true;
  req.ambiguity_margin = raw.ambiguity_margin || null;
  req.idempotency_key = raw.idempotency_key || null;
}

// --- VALIDATION ---
const requiredFields = [
  'message_id', 'tenant_id', 'channel', 'direction',
  'author_type', 'normalized_content', 'timestamp', 'source_message_ref'
];

const missingFields = requiredFields.filter(f => req[f] === undefined || req[f] === null || req[f] === '');

if (missingFields.length > 0) {
  return [{
    json: {
      _valid: 'false',
      _error: 'INVALID_INPUT',
      _missing_fields: missingFields,
      _request: req
    }
  }];
}

if (typeof req.tenant_id !== 'string' || req.tenant_id.trim().length === 0) {
  return [{
    json: {
      _valid: 'false',
      _error: 'INVALID_TENANT_ID',
      _missing_fields: ['tenant_id'],
      _request: req
    }
  }];
}

const validDirections = ['inbound', 'outbound'];
if (!validDirections.includes(req.direction)) {
  return [{
    json: {
      _valid: 'false',
      _error: 'INVALID_DIRECTION',
      _missing_fields: ['direction'],
      _request: req
    }
  }];
}

const validAuthorTypes = ['user', 'system', 'bot'];
if (!validAuthorTypes.includes(req.author_type)) {
  return [{
    json: {
      _valid: 'false',
      _error: 'INVALID_AUTHOR_TYPE',
      _missing_fields: ['author_type'],
      _request: req
    }
  }];
}

// Whitespace-only content check
if (typeof req.normalized_content === 'string' && req.normalized_content.trim().length === 0) {
  return [{
    json: {
      _valid: 'false',
      _error: 'EMPTY_CONTENT',
      _missing_fields: ['normalized_content'],
      _request: req
    }
  }];
}

// Construct validated request with all fields
return [{
  json: {
    _valid: 'true',
    message_id: req.message_id,
    tenant_id: req.tenant_id,
    channel: req.channel,
    direction: req.direction,
    author_type: req.author_type,
    normalized_content: req.normalized_content,
    timestamp: req.timestamp,
    source_message_ref: req.source_message_ref,
    author_entity_id: req.author_entity_id || null,
    explicit_thread_id: req.explicit_thread_id || req.thread_id || null,
    reply_to_message_id: req.reply_to_message_id || null,
    reply_to_thread_id: req.reply_to_thread_id || null,
    related_entity_ids: req.related_entity_ids || [],
    metadata: req.metadata || {},
    // Per-request thresholds (null = use defaults)
    _attach_threshold: req.attach_threshold || null,
    _reopen_threshold: req.reopen_threshold || null,
    _max_candidate_threads: req.max_candidate_threads || null,
    _allow_latent_reopen: req.allow_latent_reopen,
    _allow_entity_assisted_match: req.allow_entity_assisted_match,
    _ambiguity_margin: req.ambiguity_margin || null,
    _idempotency_key: req.idempotency_key || (req.tenant_id + ':' + req.message_id + ':thread_resolution:v1')
  }
}];

// TR_Select_Content_Class
// Purpose: Selects the appropriate content class for thread resolution.
// MVP: normalized_content. Phase 2: llm_safe_content.

const req = $input.all()[0].json;
const contentForResolution = req.normalized_content;

return [{
  json: {
    ...req,
    content_for_resolution: contentForResolution,
    content_class_used: 'normalized_content'
  }
}];

// TR_Check_Explicit_Refs — v2.0 (Remediated)
// Priority 1: explicit thread_id in message → shortcircuit
// Priority 1b: reply_to_thread_id WITHOUT reply_to_message_id → explicit shortcircuit
// Priority 2a: reply_to_thread_id WITH reply_to_message_id → reply linkage shortcircuit (no DB needed)
// Priority 2b: reply_to_message_id only → needs DB lookup
// Priority 3+: candidate scoring

const req = $input.all()[0].json;

// Priority 1: Explicit thread_id
if (req.explicit_thread_id) {
  return [{
    json: {
      ...req,
      _shortcircuit: 'true',
      _resolution_method: 'explicit_thread_reference',
      _resolved_thread_id: req.explicit_thread_id,
      _candidate_scores: [],
      _ambiguity_detected: false
    }
  }];
}

// Priority 1b/2a: reply_to_thread_id present
if (req.reply_to_thread_id) {
  if (req.reply_to_message_id) {
    // Reply context with known thread → reply_linkage shortcircuit
    return [{
      json: {
        ...req,
        _shortcircuit: 'true',
        _resolution_method: 'direct_reply_linkage',
        _resolved_thread_id: req.reply_to_thread_id,
        _candidate_scores: [],
        _ambiguity_detected: false
      }
    }];
  } else {
    // Thread reference via reply context without specific message → explicit ref
    return [{
      json: {
        ...req,
        _shortcircuit: 'true',
        _resolution_method: 'explicit_thread_reference',
        _resolved_thread_id: req.reply_to_thread_id,
        _candidate_scores: [],
        _ambiguity_detected: false
      }
    }];
  }
}

// Priority 2b: reply_to_message_id only → needs DB lookup
if (req.reply_to_message_id) {
  return [{
    json: {
      ...req,
      _shortcircuit: 'false',
      _check_reply_linkage: true,
      _resolution_method: null,
      _resolved_thread_id: null
    }
  }];
}

// No explicit ref → proceed to candidate scoring
return [{
  json: {
    ...req,
    _shortcircuit: 'false',
    _check_reply_linkage: false,
    _resolution_method: null,
    _resolved_thread_id: null
  }
}];

// TR_Process_Reply_Result — v2.0
// Process reply context lookup. If thread found via reply, shortcircuit.

const prevNodeItems = $('TR_Load_Reply_Context').all();
const request = $('TR_Check_Explicit_Refs').all()[0].json;

// If we weren't checking reply linkage, pass through
if (!request._check_reply_linkage) {
  return [{
    json: {
      ...request,
      _shortcircuit: 'false',
      _resolution_method: null,
      _resolved_thread_id: null
    }
  }];
}

let replyThreadId = null;
if (prevNodeItems.length > 0 && prevNodeItems[0].json && prevNodeItems[0].json.thread_id) {
  replyThreadId = prevNodeItems[0].json.thread_id;
}

if (replyThreadId) {
  return [{
    json: {
      ...request,
      _shortcircuit: 'true',
      _resolution_method: 'direct_reply_linkage',
      _resolved_thread_id: replyThreadId,
      _candidate_scores: [],
      _ambiguity_detected: false
    }
  }];
}

// No reply linkage found
return [{
  json: {
    ...request,
    _shortcircuit: 'false',
    _resolution_method: null,
    _resolved_thread_id: null
  }
}];

// TR_Score_Candidates — v2.0 (Remediated)
// Romanian-aware scoring with stemming + trigram hybrid.
// Fixes D-28 (Jaccard failure), D-29 (artificial fixtures), D-30 (no Romanian morphology).
//
// Scoring components:
//   entity_match_score: 0.0 to 0.30
//   semantic_match_score: 0.0 to 0.40 (Romanian stem + trigram hybrid)
//   temporal_proximity_score: 0.0 to 0.20
//   channel_relevance_score: 0.0 to 0.10
//   MAX POSSIBLE SCORE: 1.0

const request = $('TR_Process_Reply_Result').all()[0].json;
const candidateItems = $('TR_Load_Candidate_Threads').all();
const entityItems = $('TR_Load_Entity_Hints').all();

// Build entity lookup
const entities = {};
for (const item of entityItems) {
  if (item.json && item.json.id) {
    entities[item.json.id] = item.json;
  }
}

// If no candidates, return empty
if (!candidateItems || candidateItems.length === 0 || !candidateItems[0].json || !candidateItems[0].json.id) {
  return [{
    json: {
      ...request,
      _scored_candidates: [],
      _has_candidates: false
    }
  }];
}

const candidates = candidateItems.map(c => c.json).filter(c => c.id);
const now = new Date(request.timestamp);

// --- ROMANIAN LANGUAGE TOOLS ---

const RO_STOPWORDS = new Set([
  'si', 'cu', 'de', 'pe', 'la', 'in', 'din', 'ca', 'sa', 'nu', 'mai',
  'dar', 'sau', 'iar', 'este', 'sunt', 'fie', 'era', 'fost', 'care',
  'ce', 'cine', 'cum', 'cand', 'unde', 'pentru', 'despre', 'spre',
  'prin', 'intre', 'dupa', 'pana', 'fara', 'inca', 'tot', 'foarte',
  'acolo', 'aici', 'acum', 'apoi', 'asa', 'atunci', 'doar', 'deja',
  'ori', 'chiar', 'daca', 'ale', 'cel', 'cei', 'cele', 'lui', 'lor',
  'meu', 'mea', 'mei', 'tale', 'tau', 'sau', 'nostru', 'noastra',
  'vostru', 'voastra', 'alt', 'alta', 'alti', 'alte', 'acest',
  'aceasta', 'acesti', 'aceste', 'acel', 'acea', 'acei', 'acele',
  'care', 'care', 'unde', 'cat', 'cata', 'cati', 'cate'
]);

function roStem(word) {
  // Romanian suffix stripping — handles common morphological endings
  let w = word.toLowerCase().trim();
  if (w.length <= 3) return w;

  // Definite article suffixes (longest first)
  const suffixes = [
    'urilor', 'urilor', 'iilor', 'elor', 'ilor',
    'ului', 'ului', 'area', 'erea', 'irea', 'atea',
    'urile', 'urile',
    'ului', 'ilor', 'elor',
    'ata', 'ita', 'uta',
    'ul', 'ei', 'le', 'ii',
    'ari', 'eri', 'iri', 'uri',
    'and', 'ind', 'eza',
    'esc', 'ste',
    'at', 'it', 'ut',
    'a', 'e', 'i'
  ];

  for (const suf of suffixes) {
    if (w.length > suf.length + 2 && w.endsWith(suf)) {
      return w.slice(0, -suf.length);
    }
  }
  return w;
}

function tokenize(text) {
  if (!text) return [];
  return text.toLowerCase()
    .replace(/[^a-zA-Z0-9\u00C0-\u024F\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 1 && !RO_STOPWORDS.has(w));
}

function stemmedTokens(text) {
  return tokenize(text).map(w => roStem(w));
}

function charTrigrams(text) {
  if (!text) return new Set();
  const clean = text.toLowerCase().replace(/[^a-zA-Z0-9\u00C0-\u024F]/g, '');
  const trigrams = new Set();
  for (let i = 0; i <= clean.length - 3; i++) {
    trigrams.add(clean.substring(i, i + 3));
  }
  return trigrams;
}

function jaccardSimilarity(setA, setB) {
  if (setA.size === 0 || setB.size === 0) return 0;
  let intersection = 0;
  for (const item of setA) {
    if (setB.has(item)) intersection++;
  }
  const union = new Set([...setA, ...setB]).size;
  return union === 0 ? 0 : intersection / union;
}

// --- SCORING FUNCTIONS ---

function entityMatchScore(request, thread) {
  // Author entity matches thread primary: 0.30 (strong direct signal)
  if (request.author_entity_id && thread.primary_entity_id &&
      request.author_entity_id === thread.primary_entity_id) {
    return 0.30;
  }
  // Related entity matches thread primary: 0.30 (message explicitly mentions thread's primary entity)
  const messageRelated = request.related_entity_ids || [];
  if (thread.primary_entity_id) {
    for (const eid of messageRelated) {
      if (eid === thread.primary_entity_id) return 0.30;
    }
  }
  // Author entity in thread's related entities: 0.15
  const threadRelated = thread.related_entity_ids || [];
  if (request.author_entity_id && Array.isArray(threadRelated) && threadRelated.includes(request.author_entity_id)) {
    return 0.15;
  }
  // Any overlap between message related and thread related: 0.15
  for (const eid of messageRelated) {
    if (Array.isArray(threadRelated) && threadRelated.includes(eid)) return 0.15;
  }
  return 0.0;
}

function semanticMatchScore(messageContent, threadSummary) {
  // Romanian-aware hybrid: stemmed word Jaccard + character trigram Jaccard
  if (!messageContent || !threadSummary) return 0.0;

  // Stemmed word Jaccard
  const msgStems = new Set(stemmedTokens(messageContent));
  const sumStems = new Set(stemmedTokens(threadSummary));
  const stemJaccard = jaccardSimilarity(msgStems, sumStems);

  // Character trigram Jaccard (captures partial word matches)
  const msgTrigrams = charTrigrams(messageContent);
  const sumTrigrams = charTrigrams(threadSummary);
  const trigramJaccard = jaccardSimilarity(msgTrigrams, sumTrigrams);

  // Combined: take the max of both approaches, scale to 0-0.40
  const combined = Math.max(stemJaccard, trigramJaccard);
  return Math.min(combined * 1.6, 0.40);
}

function temporalProximityScore(messageTimestamp, threadLastActivity) {
  if (!threadLastActivity) return 0.05;
  const diffMs = now.getTime() - new Date(threadLastActivity).getTime();
  const diffHours = diffMs / (1000 * 60 * 60);
  if (diffHours <= 1) return 0.20;
  if (diffHours <= 24) return 0.15;
  if (diffHours <= 168) return 0.10;
  return 0.05;
}

function channelRelevanceScore(messageChannel, threadSourceChannels) {
  if (!threadSourceChannels || !Array.isArray(threadSourceChannels)) return 0.0;
  return threadSourceChannels.includes(messageChannel) ? 0.10 : 0.0;
}

// --- SCORE ALL CANDIDATES ---

const scored = candidates.map(thread => {
  const entScore = entityMatchScore(request, thread);
  const semScore = semanticMatchScore(request.content_for_resolution, thread.summary);
  const tempScore = temporalProximityScore(request.timestamp, thread.last_activity_at);
  const chanScore = channelRelevanceScore(request.channel, thread.source_channels);
  const totalScore = entScore + semScore + tempScore + chanScore;

  return {
    thread_id: thread.id,
    thread_status: thread.status,
    thread_title: thread.title,
    score: Math.round(totalScore * 1000) / 1000,
    entity_match: Math.round(entScore * 1000) / 1000,
    semantic_match: Math.round(semScore * 1000) / 1000,
    temporal_proximity: Math.round(tempScore * 1000) / 1000,
    channel_relevance: Math.round(chanScore * 1000) / 1000
  };
});

scored.sort((a, b) => b.score - a.score);

return [{
  json: {
    ...request,
    _scored_candidates: scored,
    _has_candidates: scored.length > 0
  }
}];

// TR_Apply_Decision_Policy — v2.0 (Remediated)
// Per-request thresholds from resolution_policy (D-05 fix).
// Removed dead code catch-all (D-17 fix).
// Documented ambiguity minimum (D-18 fix).
// Explicit latent-above-attach → reopen (D-16 fix).

const req = $input.all()[0].json;
const scored = req._scored_candidates || [];

// Per-request thresholds with defaults
const STRICT_ATTACH_THRESHOLD = req._attach_threshold || 0.75;
const REOPEN_THRESHOLD = req._reopen_threshold || 0.65;
const AMBIGUITY_MARGIN = req._ambiguity_margin || 0.05;
const AMBIGUITY_MINIMUM = 0.60; // Global minimum score for ambiguity detection
const allowLatentReopen = req._allow_latent_reopen !== false;

// No candidates at all
if (scored.length === 0) {
  return [{
    json: {
      ...req,
      _resolution_method: 'create_new_thread',
      _resolved_thread_id: null,
      _ambiguity_detected: false,
      _decision_reason: 'no_candidates_found',
      _confidence: 0.0
    }
  }];
}

const best = scored[0];
const second = scored.length > 1 ? scored[1] : null;

// Ambiguity check: top two within margin AND best >= AMBIGUITY_MINIMUM
// Note: AMBIGUITY_MINIMUM is deliberately lower than both attach and reopen thresholds.
// This catches cases where two candidates are plausible but neither dominates.
const ambiguityDetected = second !== null &&
  (best.score - second.score) < AMBIGUITY_MARGIN &&
  best.score >= AMBIGUITY_MINIMUM;

if (ambiguityDetected) {
  return [{
    json: {
      ...req,
      _resolution_method: 'create_new_thread',
      _resolved_thread_id: null,
      _ambiguity_detected: true,
      _decision_reason: 'ambiguous_candidates_top_two_within_margin',
      _confidence: best.score,
      _best_score: best.score,
      _second_score: second.score
    }
  }];
}

// Entity-semantic divergence check:
// If best candidate wins on total due to entity match, but another candidate
// has HIGHER semantic match by > 0.08, entity may be misleading.
if (scored.length >= 2) {
  const secondCand = scored[1];
  if (best.entity_match > 0 &&
      secondCand.semantic_match > best.semantic_match &&
      (secondCand.semantic_match - best.semantic_match) > 0.08) {
    return [{
      json: {
        ...req,
        _resolution_method: 'create_new_thread',
        _resolved_thread_id: null,
        _ambiguity_detected: true,
        _decision_reason: 'entity_semantic_divergence',
        _confidence: best.score,
        _best_score: best.score,
        _second_score: secondCand.score
      }
    }];
  }
}

// Active/waiting/blocked thread above attach threshold
const activeStatuses = ['active', 'waiting', 'blocked'];
if (best.score >= STRICT_ATTACH_THRESHOLD && activeStatuses.includes(best.thread_status)) {
  return [{
    json: {
      ...req,
      _resolution_method: 'attach_existing_thread',
      _resolved_thread_id: best.thread_id,
      _ambiguity_detected: false,
      _decision_reason: 'score_above_attach_threshold',
      _confidence: best.score,
      _best_score: best.score
    }
  }];
}

// Latent thread: reopen if above reopen threshold (even if above attach threshold)
// D-16 fix: latent threads are ALWAYS reopened, never "attached"
if (best.thread_status === 'latent' && best.score >= REOPEN_THRESHOLD && allowLatentReopen) {
  return [{
    json: {
      ...req,
      _resolution_method: 'reopen_latent_thread',
      _resolved_thread_id: best.thread_id,
      _ambiguity_detected: false,
      _decision_reason: 'latent_thread_above_reopen_threshold',
      _confidence: best.score,
      _best_score: best.score
    }
  }];
}

// Below all thresholds → create new thread
return [{
  json: {
    ...req,
    _resolution_method: 'create_new_thread',
    _resolved_thread_id: null,
    _ambiguity_detected: false,
    _decision_reason: 'best_score_below_all_thresholds',
    _confidence: best.score,
    _best_score: best.score
  }
}];

// TR_Build_Result — v2.0 (Remediated)
// Builds both internal and user-facing result fields.
// D-03 fix: deterministic resolution_id (no Date.now()).
// D-06 fix: explicit error: null on success.
// D-11 fix: no non-contract fields in output.
// D-02 fix: adds user contract fields (module_name, result_type, etc.).

const req = $input.all()[0].json;

// Deterministic resolution_id: hash of idempotency_key
function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return Math.abs(hash).toString(36);
}

const idempKey = req._idempotency_key || (req.tenant_id + ':' + req.message_id + ':thread_resolution:v1');
const resolutionId = 'tr_' + req.message_id + '_' + simpleHash(idempKey);

// Determine confidence
const confidence = req._confidence !== undefined ? req._confidence :
  (req._resolution_method === 'explicit_thread_reference' || req._resolution_method === 'direct_reply_linkage') ? 1.0 : 0.0;

// Determine winning_reason
const winningReason = req._decision_reason || req._resolution_method;

// Build candidate_scores for output (simplified shape for user contract)
const candidateScores = (req._scored_candidates || []).slice(0, 10).map(cs => ({
  thread_id: cs.thread_id,
  thread_status: cs.thread_status,
  score: cs.score,
  entity_match: cs.entity_match,
  semantic_match: cs.semantic_match,
  temporal_proximity: cs.temporal_proximity,
  channel_relevance: cs.channel_relevance
}));

const result = {
  // Internal contract fields (audit/orchestrator)
  resolution_id: resolutionId,
  message_id: req.message_id,
  tenant_id: req.tenant_id,
  decision: req._resolution_method,
  resolved_thread_id: req._resolved_thread_id || null,
  candidate_scores: candidateScores,
  ambiguity_detected: req._ambiguity_detected || false,
  content_class_used: req.content_class_used || 'normalized_content',
  decision_reason: winningReason,
  timestamp: new Date().toISOString(),
  error: null,
  // User contract fields
  module_name: 'thread_resolver_module',
  result_type: 'analysis',
  status: 'success',
  resolution_action: req._resolution_method,
  reopened_thread: req._resolution_method === 'reopen_latent_thread',
  created_thread: req._resolution_method === 'create_new_thread' ? {
    proposed_title: null,
    thread_type: 'operational',
    primary_entity_id: null,
    initial_summary: null
  } : null,
  confidence: Math.round(confidence * 100) / 100,
  winning_reason: winningReason,
  needs_followup: false,
  followup_requests: []
};

return [{ json: result }];

// TR_Build_Error_Result — v2.0 (Remediated)
// Builds error result with both internal and user-facing fields.

const errData = $input.all()[0].json;
const reqData = errData._request || {};

// Deterministic error resolution_id
function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(36);
}

const msgId = reqData.message_id || 'unknown';
const tenantId = reqData.tenant_id || 'unknown';
const idempKey = reqData._idempotency_key || reqData.idempotency_key || (tenantId + ':' + msgId + ':error:v1');
const resolutionId = 'tr_error_' + simpleHash(idempKey);

const result = {
  // Internal fields
  resolution_id: resolutionId,
  message_id: msgId !== 'unknown' ? msgId : null,
  tenant_id: tenantId !== 'unknown' ? tenantId : null,
  decision: 'fail_invalid_input',
  resolved_thread_id: null,
  candidate_scores: [],
  ambiguity_detected: false,
  content_class_used: 'none',
  decision_reason: errData._error + ': ' + (errData._missing_fields || []).join(', '),
  timestamp: new Date().toISOString(),
  error: {
    code: errData._error,
    missing_fields: errData._missing_fields || []
  },
  // User contract fields
  module_name: 'thread_resolver_module',
  result_type: 'error',
  status: 'failed',
  resolution_action: 'fail_invalid_input',
  reopened_thread: false,
  created_thread: null,
  confidence: 0.0,
  winning_reason: 'missing_required_field_' + (errData._missing_fields || [])[0],
  needs_followup: true,
  followup_requests: (errData._missing_fields || []).map(f => ({
    type: 'invalid_input',
    field: f,
    message: f + ' is required'
  }))
};

return [{ json: result }];

// TR_Return_Result — v2.0 (Remediated)
// Returns clean contract output with both internal and user-facing fields.
// Design note: reads from TR_Build_Result (not $input from TR_Write_Audit)
// so that audit write failure does not block result return.

const result = $('TR_Build_Result').all()[0].json;

return [{
  json: {
    // Internal contract fields
    resolution_id: result.resolution_id,
    message_id: result.message_id,
    tenant_id: result.tenant_id,
    decision: result.decision,
    resolved_thread_id: result.resolved_thread_id,
    candidate_scores: result.candidate_scores,
    ambiguity_detected: result.ambiguity_detected,
    content_class_used: result.content_class_used,
    decision_reason: result.decision_reason,
    timestamp: result.timestamp,
    error: result.error,
    // User contract fields
    module_name: result.module_name,
    result_type: result.result_type,
    status: result.status,
    resolution_action: result.resolution_action,
    reopened_thread: result.reopened_thread,
    created_thread: result.created_thread,
    confidence: result.confidence,
    winning_reason: result.winning_reason,
    needs_followup: result.needs_followup,
    followup_requests: result.followup_requests
  }
}];

// TR_Build_EC_Envelope — Phase 8 edge-1 adapter.
// Reshapes TR_Return_Result (flat) into EC_Validate_Input (flat) shape.
const src = $json || {};
// If TR already surfaced an error, bail out and propagate unchanged.
if (src.error || src.status === 'failed' || src.status_kind === 'failed') {
  return [{ json: src }];
}
const tenant_id = src.tenant_id;
const thread_id = src.resolved_thread_id;
const trigger_message_id = src.message_id;
const resolution_method = src.resolution_action || src.decision || null;
const resolved_at = src.timestamp || null;
if (!tenant_id || !thread_id || !trigger_message_id) {
  return [{ json: {
    status_kind: 'failed',
    result_type: 'error',
    module_name: 'tr_to_ec_adapter',
    error: {
      code: 'MISSING_REQUIRED_IDS',
      message: 'TR result lacks tenant_id, resolved_thread_id, or message_id.',
      missing_fields: ['tenant_id','resolved_thread_id','message_id'].filter(f => !src[f])
    }
  } }];
}
const idempotency_key = `tr-to-ec:${tenant_id}:${trigger_message_id}:v1`;
return [{ json: {
  tenant_id, thread_id, trigger_message_id,
  resolution_method, resolved_at, idempotency_key
} }];
